import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"Instant Answers & Keyword Features","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/instant-answers.md","filePath":"user-guide/instant-answers.md","lastUpdated":1788085660000}'),i={name:"user-guide/instant-answers.md"};function s(r,e,l,d,c,g){return a(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="instant-answers-keyword-features" tabindex="-1">Instant Answers &amp; Keyword Features <a class="header-anchor" href="#instant-answers-keyword-features" aria-label="Permalink to &quot;Instant Answers &amp; Keyword Features&quot;">​</a></h1><p>Beyond local file search, Lertaro includes a powerful suite of instant calculations, system tools, and keyword-triggered plugin extensions. Answers appear instantly without waiting for file search results.</p><h2 id="_1-always-active-instant-answers" tabindex="-1">1. Always Active Instant Answers <a class="header-anchor" href="#_1-always-active-instant-answers" aria-label="Permalink to &quot;1. Always Active Instant Answers&quot;">​</a></h2><p>These features do not require any trigger prefix; they activate automatically whenever the input matches their patterns:</p><h3 id="calculator-base-conversion" tabindex="-1">Calculator &amp; Base Conversion <a class="header-anchor" href="#calculator-base-conversion" aria-label="Permalink to &quot;Calculator &amp; Base Conversion&quot;">​</a></h3><p>Type any arithmetic expression directly into the search bar. Results appear in real time. Press <code>Enter</code> to copy the evaluated result to the clipboard:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>12 * (4 + 3)</span></span>
<span class="line"><span>100 * (1 - 0.15)</span></span></code></pre></div><p>Common number base conversions are supported out of the box:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>255 to hex</span></span>
<span class="line"><span>0xFF to dec</span></span>
<span class="line"><span>101010 to bin</span></span></code></pre></div><h3 id="environment-variable-expansion-inspection" tabindex="-1">Environment Variable Expansion &amp; Inspection <a class="header-anchor" href="#environment-variable-expansion-inspection" aria-label="Permalink to &quot;Environment Variable Expansion &amp; Inspection&quot;">​</a></h3><ul><li><strong>Expand Variables</strong>: Type <code>%NAME%</code> (e.g. <code>%PATH%</code>, <code>%APPDATA%</code>) to inspect its evaluated value. Multi-path variables such as <code>PATH</code> are split into clear line-by-line lists for inspection.</li><li><strong>Fuzzy Search Variables</strong>: Type <code>%</code> followed by a keyword (e.g. <code>%temp</code>) to fuzzy-search across all system and user environment variables.</li></ul><h3 id="quick-command-execution" tabindex="-1">Quick Command Execution <a class="header-anchor" href="#quick-command-execution" aria-label="Permalink to &quot;Quick Command Execution&quot;">​</a></h3><p>Run commands directly without launching a terminal window first:</p><ul><li><code>#&lt;command&gt;</code>: Opens a command prompt and executes the command <strong>with Administrator privileges</strong> (e.g. <code>#sfc /scannow</code> or <code>#net start Lertaro.Service</code>).</li><li><code>$&lt;command&gt;</code>: Opens a command prompt and executes the command with <strong>standard user permissions</strong> (e.g. <code>$ping 1.1.1.1</code> or <code>$ipconfig /all</code>).</li></ul><h3 id="direct-url-navigation" tabindex="-1">Direct URL Navigation <a class="header-anchor" href="#direct-url-navigation" aria-label="Permalink to &quot;Direct URL Navigation&quot;">​</a></h3><p>Type or paste any URL beginning with <code>http://</code> or <code>https://</code> and press <code>Enter</code> to open it immediately in your default browser. When the query has no search results and begins with a bare domain name, the Quick Search Window automatically fills in <code>https://</code> and moves the caret to the end; inputs that already include a protocol are left unchanged.</p><h3 id="clipboard-text-in-the-quick-search-window" tabindex="-1">Clipboard text in the Quick Search Window <a class="header-anchor" href="#clipboard-text-in-the-quick-search-window" aria-label="Permalink to &quot;Clipboard text in the Quick Search Window&quot;">​</a></h3><p>When the Quick Search Window is summoned without prefilled text, a non-empty clipboard text is imported and selected automatically if it differs from the last clipboard value imported by that window. The same value is not imported repeatedly, and prefilled queries from a URI or from returning from the full search window are never overwritten.</p><h2 id="_2-keyword-triggered-plugin-extensions" tabindex="-1">2. Keyword-Triggered Plugin Extensions <a class="header-anchor" href="#_2-keyword-triggered-plugin-extensions" aria-label="Permalink to &quot;2. Keyword-Triggered Plugin Extensions&quot;">​</a></h2><p>By typing a short <strong>trigger keyword + space</strong> followed by your query, you can invoke dedicated plugin capabilities. All keywords can be customized under <a href="./settings/plugins.html"><strong>Settings → Plugins</strong></a>.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Default Keyword</th><th style="text-align:left;">Plugin Name</th><th style="text-align:left;">Description &amp; Use Case</th><th style="text-align:left;">Example Usage</th></tr></thead><tbody><tr><td style="text-align:left;"><code>ps</code></td><td style="text-align:left;"><strong>Process Manager</strong></td><td style="text-align:left;">Search running processes by name, PID, or window title (supports pinyin). Press Enter to terminate.</td><td style="text-align:left;"><code>ps chrome</code> or <code>ps 1234</code></td></tr><tr><td style="text-align:left;"><code>win</code></td><td style="text-align:left;"><strong>Window Switcher</strong></td><td style="text-align:left;">Search and jump to active application windows with live background thumbnail snapshots.</td><td style="text-align:left;"><code>win code</code> or <code>win browser</code></td></tr><tr><td style="text-align:left;"><code>bm</code></td><td style="text-align:left;"><strong>Browser Data</strong></td><td style="text-align:left;">Search bookmarks and history from Chrome, Edge, and Firefox profiles (history and bookmarks toggleable independently).</td><td style="text-align:left;"><code>bm github</code></td></tr><tr><td style="text-align:left;"><code>set</code></td><td style="text-align:left;"><strong>Settings Search</strong></td><td style="text-align:left;">Fuzzy-search Lertaro&#39;s internal settings. Selecting an item jumps directly to that setting page and highlights it.</td><td style="text-align:left;"><code>set hotkey</code> or <code>set fuzzy</code></td></tr><tr><td style="text-align:left;"><code>flow</code></td><td style="text-align:left;"><strong>Flow Launcher Bridge</strong></td><td style="text-align:left;">Lists loaded Flow.Launcher plugins and their action keywords, connecting with the Flow community ecosystem.</td><td style="text-align:left;"><code>flow</code></td></tr></tbody></table><h2 id="_3-web-search-engines" tabindex="-1">3. Web Search Engines <a class="header-anchor" href="#_3-web-search-engines" aria-label="Permalink to &quot;3. Web Search Engines&quot;">​</a></h2><p>The Web Search plugin provides built-in shortcuts for major search engines. Type the prefix followed by your query to search in your default browser:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Shortcut</th><th style="text-align:left;">Search Engine</th><th style="text-align:left;">Example</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>bd</code></td><td style="text-align:left;">Baidu</td><td style="text-align:left;"><code>bd deep learning</code></td><td style="text-align:left;">Search via Baidu</td></tr><tr><td style="text-align:left;"><code>g</code></td><td style="text-align:left;">Google</td><td style="text-align:left;"><code>g lertaro github</code></td><td style="text-align:left;">Search via Google</td></tr><tr><td style="text-align:left;"><code>bing</code></td><td style="text-align:left;">Bing</td><td style="text-align:left;"><code>bing microsoft docs</code></td><td style="text-align:left;">Search via Bing</td></tr><tr><td style="text-align:left;"><code>gh</code></td><td style="text-align:left;">GitHub</td><td style="text-align:left;"><code>gh Lertaro</code></td><td style="text-align:left;">Search directly across GitHub repositories</td></tr><tr><td style="text-align:left;"><code>wiki</code></td><td style="text-align:left;">Wikipedia</td><td style="text-align:left;"><code>wiki quantum computing</code></td><td style="text-align:left;">Look up Wikipedia entries</td></tr><tr><td style="text-align:left;"><code>yt</code></td><td style="text-align:left;">YouTube</td><td style="text-align:left;"><code>yt lofi hip hop</code></td><td style="text-align:left;">Search YouTube videos</td></tr></tbody></table><p>You can add, edit, or remove search engines and custom URL templates under <strong>Settings → Plugins → Web Search → Configure</strong>.</p><h2 id="_4-instant-translation" tabindex="-1">4. Instant Translation <a class="header-anchor" href="#_4-instant-translation" aria-label="Permalink to &quot;4. Instant Translation&quot;">​</a></h2><p>Type the default trigger <code>tr</code> followed by text to translate it automatically into the language currently selected in Lertaro&#39;s interface:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tr Hello, how are you today?</span></span></code></pre></div><ul><li>Results appear asynchronously as you type; press <code>Enter</code> to copy the translation.</li><li>Customize the trigger keyword under <strong>Settings → Plugins → Translator → Configure</strong>.</li></ul><h2 id="_5-file-filters" tabindex="-1">5. File Filters <a class="header-anchor" href="#_5-file-filters" aria-label="Permalink to &quot;5. File Filters&quot;">​</a></h2><p>Under <strong>Settings → Plugins → File Filters → Configure</strong>, you can create isolated search scopes for specific folders and extensions:</p><ul><li><strong>Monitored Folders</strong>: Recursively scan specific working directories (e.g. <code>D:\\Engineering\\Drawings</code>).</li><li><strong>Matching Rules</strong>: Specify patterns such as <code>*.dwg;*.dxf</code> or <code>*.pdf;*.docx</code>.</li><li><strong>Trigger Keyword</strong>: Assign an exclusive keyword (e.g. <code>cad</code>), allowing you to isolate searches (e.g. <code>cad bracket_assembly</code>).</li></ul><h2 id="_6-custom-commands" tabindex="-1">6. Custom Commands <a class="header-anchor" href="#_6-custom-commands" aria-label="Permalink to &quot;6. Custom Commands&quot;">​</a></h2><p>Under <strong>Settings → Plugins → Custom Commands → Configure</strong>, wrap complex scripts, tools, or applications into concise commands:</p><ul><li><strong>Parameter Placeholders</strong>: Supports positional placeholders <code>%s1</code>, <code>%s2</code>... and full query capture <code>%s</code>.</li><li><strong>Quick Navigation Integration</strong>: Check &quot;Show in Quick Navigation&quot; to pin the command directly into the <a href="./hotkeys.html#3-quick-navigation-mouse-triggers"><strong>Quick Navigation</strong></a> menu, with optional <code>/</code> submenu paths (e.g. <code>DevTools/RestartService</code>).</li></ul>`,35)])])}const p=t(i,[["render",s]]);export{u as __pageData,p as default};
